@pytest.mark.parametrize('n_samples', [101, 102, 103])
@pytest.mark.parametrize('n_components', [2, 4, None])
@pytest.mark.parametrize('batch_size', [10, 20])
def test_incremental_pca_short_final_batch(n_samples, n_components, batch_size):
    # A short final batch must not raise or cause any samples to be discarded.
    X = iris.data[:n_samples]
    ipca = IncrementalPCA(n_components=n_components, batch_size=batch_size)
    X_transformed = ipca.fit_transform(X)

    expected_components = n_components or X.shape[1]
    assert X_transformed.shape == (n_samples, expected_components)
    assert ipca.n_samples_seen_ == n_samples
    assert np.isfinite(X_transformed).all()
    assert_array_almost_equal(ipca.mean_, X.mean(axis=0))
    assert_array_almost_equal(ipca.var_, X.var(axis=0))


